/**
 * The shape of the pinned SimulationCraft GCD-semantics artifact, and a runtime
 * validator for it.
 *
 * The artifact is generated by `scripts/authority/extract-simc-gcd.mjs` from one
 * exact SimulationCraft commit and committed. Nothing here reaches the network,
 * and nothing here parses C++.
 *
 * WHAT THE ARTIFACT STORES, AND WHAT IT DELIBERATELY DOES NOT
 *
 * It stores `baseGcdMs`: the `spell_data_t::_gcd` field, verbatim, in
 * milliseconds. That is the number SimulationCraft assigns to `trigger_gcd` for
 * a spell-backed action, and `trigger_gcd > 0` is the exact predicate the engine
 * uses to decide whether an executed action consumed the rotational slot.
 *
 * It does NOT store an execution lane. The lane is `baseGcdMs > 0`, derived at
 * read time, so there is one source of truth and a stored lane cannot drift away
 * from the number it was supposed to summarise. A validator rejects an artifact
 * that stores one.
 *
 * WHY A RUNTIME VALIDATOR FOR AN IMPORTED JSON FILE
 *
 * `resolveJsonModule` gives the import a structural type inferred from the file
 * on disk, which is not a checked contract: a regenerated artifact with a
 * missing field would either fail to compile somewhere confusing or slip through
 * widened. Validating explicitly means a malformed artifact fails closed at load
 * with a reason, in the same style as every other boundary in this codebase.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_GCD_ARTIFACT_VERSION = 1;

/** One pinned upstream file the artifact was derived from. */
export interface GcdArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface GcdArtifactProvenance {
  readonly repository: string;
  /** The exact pinned SimulationCraft commit. Never a branch name. */
  readonly commitSha: string;
  readonly sources: readonly GcdArtifactSource[];
  /** The World of Warcraft client build the generated data was produced from. */
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  /** The upstream field the value was read from. Recorded so the claim is checkable. */
  readonly gcdFieldName: string;
  readonly gcdFieldUnits: string;
  /**
   * How the `abilities` half was established: parsed out of the generated DBC
   * table. Stated explicitly so it cannot be confused with the hand-reviewed
   * token bindings, which carry their own, different method.
   */
  readonly abilityDataMethod: string;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  /**
   * Why this dataset carries no fight-derived applicability gate.
   *
   * Present so the absence of a gate is a stated decision rather than an
   * oversight a reader has to infer. See `src/data/provenance.ts`.
   */
  readonly applicabilityNote: string;
}

export interface AbilityGcdRecord {
  /** The canonical game spell id. The identity. */
  readonly abilityGameId: number;
  /** `spell_data_t::_gcd`, verbatim, in milliseconds. */
  readonly baseGcdMs: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
}

/**
 * How a token -> spell-id relation was established.
 *
 * ONE member, and it says "a human read C++". The artifact carries two kinds of
 * knowledge and they must never be confused:
 *
 *     token    -> candidate spell ids   HAND_REVIEWED_CPP_CONTROL_FLOW
 *     spell id -> baseGcdMs             MACHINE_EXTRACTED_DBC_RECORD
 *
 * The generator parses the generated DBC tables; it does NOT parse
 * `sc_rogue.cpp`, and nothing here may present a hand-reviewed reading as though
 * it had been extracted. `MACHINE_EXTRACTED_DBC_RECORD` is deliberately NOT a
 * member of this union, so a binding cannot claim it.
 */
export type TokenBindingMethod = "HAND_REVIEWED_CPP_CONTROL_FLOW";

export const TOKEN_BINDING_METHODS = [
  "HAND_REVIEWED_CPP_CONTROL_FLOW",
] as const satisfies readonly TokenBindingMethod[];

/** The method marker on the machine-extracted half. Never valid on a binding. */
export const MACHINE_EXTRACTED_METHOD = "MACHINE_EXTRACTED_DBC_RECORD";

/**
 * Where a hand-reviewed token binding came from, precisely enough to re-read.
 *
 * `sourceSha256` is measured from the file by the generator, not transcribed, so
 * a reviewer can confirm they are reading the same bytes the binding rests on.
 */
export interface TokenBindingProvenance {
  readonly method: TokenBindingMethod;
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly symbol: string;
  readonly startLine: number;
  readonly endLine: number;
  /** The reviewed reading, in the reviewer's words. */
  readonly sourceNote: string;
  /**
   * A generated table the id was additionally confirmed against, where one
   * exists. Corroboration only — it can confirm that an id IS a class ability,
   * never that a given APL token uses it.
   */
  readonly crossCheck: string;
}

/**
 * One SimulationCraft action token and every spell id it can resolve to.
 *
 * A LIST, not a single id, because a token is not always one spell. The pinned
 * `thistle_tea` binding branches on talent state this build does not resolve, so
 * both reachable records are recorded and neither branch is chosen.
 */
export interface TokenBindingRecord {
  readonly simcToken: string;
  readonly candidateAbilityGameIds: readonly number[];
  readonly binding: TokenBindingProvenance;
}

export interface GcdSemanticsArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: GcdArtifactProvenance;
  readonly abilities: readonly AbilityGcdRecord[];
  readonly tokenBindings: readonly TokenBindingRecord[];
}

/** Field names that must NOT appear on a record: they are derived, not stored. */
export const FORBIDDEN_DERIVED_GCD_KEYS = ["executionLane", "lane", "isOffGcd", "consumesGcd"] as const;

export type GcdArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "MALFORMED_ABILITIES"
  | "MALFORMED_ABILITY"
  | "DUPLICATE_ABILITY_ID"
  | "MALFORMED_TOKEN_BINDINGS"
  | "MALFORMED_TOKEN_BINDING"
  | "MALFORMED_BINDING_PROVENANCE"
  | "DUPLICATE_TOKEN"
  | "UNKNOWN_CANDIDATE_ABILITY";

export type GcdArtifactValidation =
  | { readonly ok: true; readonly artifact: GcdSemanticsArtifact }
  | { readonly ok: false; readonly reason: GcdArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function int(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) ? value : null;
}

function invalid(reason: GcdArtifactValidationReason, detail: string): GcdArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly GcdArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: GcdArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = int(raw, "byteLength");
    // A pinned source must carry a real file hash. A placeholder here would mean
    // the dataset is not actually traceable to a file anyone can re-read.
    if (path === null || sha256 === null || byteLength === null) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    if (byteLength <= 0) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

/**
 * Validates one hand-reviewed binding's provenance.
 *
 * Every field is required. A binding that could omit its method, its source or
 * its hash would be indistinguishable from a machine-extracted fact, which is
 * the exact confusion this record exists to prevent.
 */
function validateBindingProvenance(value: unknown): TokenBindingProvenance | null {
  if (!isRecord(value)) return null;
  const method = str(value, "method");
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const symbol = str(value, "symbol");
  const sourceNote = str(value, "sourceNote");
  const crossCheck = str(value, "crossCheck");
  const startLine = int(value, "startLine");
  const endLine = int(value, "endLine");

  if (
    method === null ||
    sourcePath === null ||
    sourceSha256 === null ||
    symbol === null ||
    sourceNote === null ||
    crossCheck === null ||
    startLine === null ||
    endLine === null
  ) {
    return null;
  }
  // Only a hand-reviewed method is expressible. A binding claiming to be
  // machine-extracted would be asserting that this project parses C++.
  if (!(TOKEN_BINDING_METHODS as readonly string[]).includes(method)) return null;
  if (!/^[0-9a-f]{64}$/.test(sourceSha256)) return null;
  if (startLine <= 0 || endLine < startLine) return null;

  return {
    method: method as TokenBindingMethod,
    sourcePath,
    sourceSha256,
    symbol,
    startLine,
    endLine,
    sourceNote,
    crossCheck,
  };
}

function validateProvenance(value: unknown): GcdArtifactProvenance | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const gcdFieldName = str(value, "gcdFieldName");
  const gcdFieldUnits = str(value, "gcdFieldUnits");
  const abilityDataMethod = str(value, "abilityDataMethod");
  const extractedOn = str(value, "extractedOn");
  const applicabilityNote = str(value, "applicabilityNote");
  const clientDataHotfixBuild = int(value, "clientDataHotfixBuild");
  const extractorVersion = int(value, "extractorVersion");
  const sources = validateSources(value["sources"]);

  if (
    repository === null ||
    commitSha === null ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixHash === null ||
    gcdFieldName === null ||
    gcdFieldUnits === null ||
    abilityDataMethod === null ||
    extractedOn === null ||
    applicabilityNote === null ||
    clientDataHotfixBuild === null ||
    extractorVersion === null ||
    sources === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;
  if (!/^[0-9a-f]{64}$/.test(clientDataHotfixHash)) return null;
  // The unit is the whole meaning of the number. An artifact that did not state
  // it, or stated a different one, must not be read as milliseconds.
  if (gcdFieldUnits !== "MILLISECONDS") return null;
  // The ability half must positively claim to be machine-extracted. Anything
  // else would leave the two kinds of knowledge indistinguishable.
  if (abilityDataMethod !== MACHINE_EXTRACTED_METHOD) return null;

  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    gcdFieldName,
    gcdFieldUnits,
    abilityDataMethod,
    extractedOn,
    extractorVersion,
    applicabilityNote,
  };
}

export function validateGcdSemanticsArtifact(value: unknown): GcdArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  const artifactVersion = int(value, "artifactVersion");
  if (artifactVersion !== SUPPORTED_GCD_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(artifactVersion)} is not ${SUPPORTED_GCD_ARTIFACT_VERSION}`,
    );
  }

  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === null) {
    return invalid(
      "MALFORMED_PROVENANCE",
      "provenance is incomplete, a hash is not a hash, or the GCD field unit is not MILLISECONDS",
    );
  }

  const abilitiesRaw = value["abilities"];
  if (!Array.isArray(abilitiesRaw) || abilitiesRaw.length === 0) {
    return invalid("MALFORMED_ABILITIES", "abilities is not a non-empty array");
  }

  const abilities: AbilityGcdRecord[] = [];
  const seenIds = new Set<number>();
  for (let index = 0; index < abilitiesRaw.length; index += 1) {
    const raw = abilitiesRaw[index];
    if (!isRecord(raw)) return invalid("MALFORMED_ABILITY", `abilities[${index}] is not an object`);
    for (const forbidden of FORBIDDEN_DERIVED_GCD_KEYS) {
      if (forbidden in raw) {
        return invalid(
          "MALFORMED_ABILITY",
          `abilities[${index}] stores derived field '${forbidden}'; the lane must be derived from baseGcdMs`,
        );
      }
    }
    const abilityGameId = int(raw, "abilityGameId");
    const baseGcdMs = int(raw, "baseGcdMs");
    // Bound to a short local on purpose. Spelling the field name next to `===`
    // would trip the boundary sweep that bans comparing an ability NAME, and
    // that sweep is deliberately blunt and unexempted — so the code moves, not
    // the rule.
    const nameEn = str(raw, "displayNameEn");
    if (abilityGameId === null || baseGcdMs === null || nameEn === null) {
      return invalid("MALFORMED_ABILITY", `abilities[${index}] is missing required fields`);
    }
    if (abilityGameId <= 0) {
      return invalid("MALFORMED_ABILITY", `abilities[${index}] has a non-positive abilityGameId`);
    }
    // `_gcd` is `unsigned` upstream. A negative here would mean the extractor
    // read the wrong column, and a lane derived from it would be meaningless.
    if (baseGcdMs < 0) {
      return invalid("MALFORMED_ABILITY", `abilities[${index}] has a negative baseGcdMs`);
    }
    if (seenIds.has(abilityGameId)) {
      return invalid("DUPLICATE_ABILITY_ID", String(abilityGameId));
    }
    seenIds.add(abilityGameId);
    abilities.push({ abilityGameId, baseGcdMs, displayNameEn: nameEn });
  }

  const bindingsRaw = value["tokenBindings"];
  if (!Array.isArray(bindingsRaw) || bindingsRaw.length === 0) {
    return invalid("MALFORMED_TOKEN_BINDINGS", "tokenBindings is not a non-empty array");
  }

  const tokenBindings: TokenBindingRecord[] = [];
  const seenTokens = new Set<string>();
  for (let index = 0; index < bindingsRaw.length; index += 1) {
    const raw = bindingsRaw[index];
    if (!isRecord(raw)) return invalid("MALFORMED_TOKEN_BINDING", `tokenBindings[${index}] is not an object`);
    const simcToken = str(raw, "simcToken");
    const candidatesRaw = raw["candidateAbilityGameIds"];
    if (simcToken === null || !Array.isArray(candidatesRaw)) {
      return invalid("MALFORMED_TOKEN_BINDING", `tokenBindings[${index}] is missing required fields`);
    }
    const binding = validateBindingProvenance(raw["binding"]);
    if (binding === null) {
      return invalid(
        "MALFORMED_BINDING_PROVENANCE",
        `tokenBindings[${index}] ('${simcToken}') does not carry a complete hand-reviewed binding provenance`,
      );
    }
    // An empty candidate list would be an unresolved binding wearing the shape of
    // a resolved one. A token we cannot bind must be ABSENT, so the reader gets
    // UNKNOWN rather than a set that vacuously agrees on a lane.
    if (candidatesRaw.length === 0) {
      return invalid("MALFORMED_TOKEN_BINDING", `tokenBindings[${index}] ('${simcToken}') has no candidates`);
    }
    const candidateAbilityGameIds: number[] = [];
    for (const candidate of candidatesRaw) {
      if (typeof candidate !== "number" || !Number.isSafeInteger(candidate) || candidate <= 0) {
        return invalid(
          "MALFORMED_TOKEN_BINDING",
          `tokenBindings[${index}] ('${simcToken}') has a bad candidate`,
        );
      }
      if (!seenIds.has(candidate)) {
        return invalid(
          "UNKNOWN_CANDIDATE_ABILITY",
          `tokenBindings[${index}] ('${simcToken}') names ability ${candidate}, which has no GCD record`,
        );
      }
      candidateAbilityGameIds.push(candidate);
    }
    if (seenTokens.has(simcToken)) {
      return invalid("DUPLICATE_TOKEN", simcToken);
    }
    seenTokens.add(simcToken);
    tokenBindings.push({ simcToken, candidateAbilityGameIds, binding });
  }

  return {
    ok: true,
    artifact: { artifactVersion, datasetId, artifactRevision, provenance, abilities, tokenBindings },
  };
}
